import {useCallback,useEffect,useMemo,useRef,useState} from 'react';
import Papa from 'papaparse';
import {AreaChart,Area,BarChart,Bar,CartesianGrid,Cell,Legend,LineChart,Line,PieChart,Pie,ResponsiveContainer,Tooltip,XAxis,YAxis} from 'recharts';
import {AlertCircle,ArrowDownToLine,ArrowLeft,ArrowRight,BarChart3,BookOpen,BrainCircuit,Check,ChevronDown,ChevronRight,CloudUpload,Code2,Database,Download,FileText,FlaskConical,FolderOpen,Gauge,GitBranch,GraduationCap,Info,Layers,Lightbulb,Menu,MessageSquareText,Play,RefreshCw,Search,Settings2,ShieldCheck,Shuffle,Sparkles,Split,Target,TrendingUp,WandSparkles,Workflow,X} from 'lucide-react';
import {examples} from './data/samples';
