import {cosine,documentLengths,fitVectorizer,frequencies} from './nlp/analysis';
import {scoreSentiment,sentimentCounts} from './nlp/sentiment';
import {learnBPE,bpeTokenize} from './nlp/bpe';
import {runLDA} from './nlp/lda';
