type IconComponent=typeof Database;
const nav:{id:Section;name:string;sub:string;icon:IconComponent;unit:string}[]=[
  {id:'inicio',name:'Inicio',sub:'Tu recorrido',icon:GraduationCap,unit:'00'},
  {id:'datos',name:'Mis datasets',sub:'Importar y explorar',icon:Database,unit:'01'},
  {id:'limpieza',name:'Preprocesamiento',sub:'Limpiar y tokenizar',icon:WandSparkles,unit:'02'},
  {id:'explorar',name:'EDA de texto',sub:'Nube y frecuencias',icon:BarChart3,unit:'03'},
  {id:'vectores',name:'Vectorización',sub:'BoW · TF-IDF · BPE',icon:Layers,unit:'04'},
  {id:'sentimientos',name:'Sentimientos',sub:'Opiniones y polaridad',icon:MessageSquareText,unit:'05'},
  {id:'topicos',name:'Tópicos LDA',sub:'Temas emergentes',icon:GitBranch,unit:'06'},
  {id:'clasificacion',name:'Clasificación',sub:'NB · LR · SVM',icon:BrainCircuit,unit:'07'},
  {id:'conceptos',name:'Aula y desafíos',sub:'Teoría y evaluación',icon:BookOpen,unit:'08'}
];
const chapters=[
  {title:'Datos no tabulares',text:'El texto es variable y ambiguo. Una misma palabra puede adquirir significados distintos según el contexto.',example:'«Banco» puede ser una entidad financiera o un asiento.'},
  {title:'NLU vs NLG',text:'NLU interpreta el lenguaje (sentimientos, entidades, intención); NLG genera lenguaje a partir de datos.',example:'NLU: detectar un reclamo. NLG: redactar la respuesta.'},
  {title:'Tokenización',text:'Separa texto en tokens: palabras, caracteres o subpalabras. Un token no siempre equivale a una palabra.',example:'«aprendiendo» → «aprend» + «iendo» (segmentación ilustrativa).'},
  {title:'Normalización',text:'Unifica variantes superficiales. Puede incluir minúsculas, tildes, signos y eliminación de ruido HTML.',example:'«EXCELENTE!!!» → «excelente», si se habilitan las reglas.'},
  {title:'Stemming',text:'El algoritmo Snowball reduce palabras a stems, que pueden no existir como palabras reales.',example:'«corriendo» → «corr» (aproximadamente).'},
  {title:'Lematización',text:'Busca la forma canónica de una palabra con información lingüística. La demo usa un diccionario pequeño; spaCy es más preciso.',example:'«fueron» puede corresponder a «ser» o «ir» según el contexto.'},
  {title:'Stop words',text:'Términos comunes que a veces se excluyen en modelos estadísticos. La negación es crítica para sentimiento.',example:'«No es bueno» ≠ «Es bueno». Nunca borres «no» automáticamente.'},
  {title:'Bag of Words',text:'Representa cada documento como un vector de frecuencias, ignorando el orden de las palabras.',example:'«perro muerde hombre» y «hombre muerde perro» tienen el mismo BoW.'},
  {title:'TF-IDF',text:'Pondera los términos con su frecuencia en cada documento y su rareza global. Suele normalizarse con norma L2.',example:'TF × [log((N+1)/(df+1))+1] y normalización L2.'},
  {title:'Embeddings',text:'Los vectores densos capturan patrones semánticos aprendidos. No se calculan en esta SPA: requieren un modelo preentrenado.',example:'«auto» y «coche» pueden quedar cercanos en un embedding.'},
  {title:'OOV y subpalabras',text:'Palabras fuera del vocabulario se ignoran en BoW/TF-IDF. BPE permite dividir palabras poco frecuentes en unidades conocidas.',example:'La demo entrena un BPE de caracteres con pares frecuentes.'},
  {title:'Sparsity',text:'Un documento usa pocos términos del vocabulario total, produciendo matrices con muchos ceros.',example:'50 palabras distintas en un vocabulario de 50.000 → ≈99,9% de ceros.'},
  {title:'Sentimiento',text:'Identifica opiniones positivas, negativas o neutras. El léxico local es interpretable, pero no comprende ironías.',example:'«¡Genial! Se retrasó 5 horas» puede confundir un modelo léxico.'},
  {title:'Modelado LDA',text:'Encuentra mezclas probabilísticas de temas a partir de patrones de palabras. Los tópicos deben interpretarse y nombrarse.',example:'«factura, cobro, pago» sugiere un tópico de facturación.'},
  {title:'Clasificación baseline',text:'Entrenamos NB, regresión logística y SVM lineal con datos etiquetados. F1 macro importa con clases desbalanceadas.',example:'Evita leakage: ajustar TF-IDF solo en el conjunto train.'},
  {title:'Domain shift',text:'Un modelo entrenado en reseñas puede generalizar mal a términos médicos, legales o regionales.',example:'«Impredecible» es positivo en cine y negativo en frenos.'}
];
const quiz=[
  {q:'¿Qué técnica conserva el orden de las palabras?',answers:['Bag of Words básico','TF-IDF de unigramas','Un Transformer con posiciones'],correct:2,explain:'BoW y TF-IDF sin n-gramas ignoran el orden. Un Transformer incorpora información posicional.'},
  {q:'¿Por qué no debemos quitar siempre «no»?',answers:['Porque altera el significado de una negación','Porque ocupa mucha memoria','Porque impide el stemming'],correct:0,explain:'«No funciona» y «funciona» tienen polaridades diferentes.'},
  {q:'¿Dónde se debe hacer fit del vectorizador?',answers:['En train y test juntos','Solo en train','Solo en test'],correct:1,explain:'El vocabulario y el IDF se aprenden del entrenamiento para evitar filtración de información.'},
  {q:'¿Qué mide F1 macro?',answers:['Solo el acierto de la clase mayoritaria','La media de F1 por clase, con igual peso','El tamaño del vocabulario'],correct:1,explain:'El F1 macro no permite que una clase mayoritaria oculte todos los errores en clases raras.'}
];
const palette=['#ff4387','#ff9d42','#8f47d6','#42b5a8','#6256c4','#cf775f'];
const n=(v:number,d=0)=>v.toLocaleString('es-AR',{maximumFractionDigits:d});
const pct=(v:number)=>`${(v*100).toFixed(1)}%`;
const truncated=(s:string,length=145)=>s.length>length?s.slice(0,length)+'…':s;
function saveBlob(text:string,name:string,mime='text/plain;charset=utf-8'){
  const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);
}
function Toggler({name,checked,onChange,desc}:{name:string;checked:boolean;onChange:(v:boolean)=>void;desc?:string}){
  return <label className="toggle-row"><div><strong>{name}</strong>{desc&&<small>{desc}</small>}</div><input className="toggle" type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)} /></label>;
}
function Pill({children,tone='light'}:{children:React.ReactNode;tone?:'light'|'pink'|'orange'|'dark'|'green'}){return <span className={`pill ${tone}`}>{children}</span>}
function PanelTitle({title,desc,action}:{title:string;desc?:string;action?:React.ReactNode}){return <div className="panel-title"><div><h3>{title}</h3>{desc&&<p>{desc}</p>}</div>{action}</div>}
function Title({eyebrow,title,desc}:{eyebrow:string;title:string;desc:string}){return <div className="section-heading"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{desc}</p></div>}
function Metric({label,value,detail,icon:Icon}:{label:string;value:string|number;detail:string;icon:IconComponent}){return <div className="metric"><div className="metric-icon"><Icon size={19}/></div><strong>{value}</strong><span>{label}</span><small>{detail}</small></div>}
function Empty({title,detail}:{title:string;detail:string}){return <div className="empty"><Database size={30}/><strong>{title}</strong><p>{detail}</p></div>}
function RowPreview({columns,rows,max=7}:{columns:string[];rows:Row[];max?:number}){return <div className="table-scroll"><table className="data-table"><thead><tr><th>#</th>{columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.slice(0,max).map((r,i)=><tr key={i}><td className="index">{i+1}</td>{columns.map(c=><td key={c} title={r[c]}>{truncated(r[c]??'',92)}</td>)}</tr>)}</tbody></table></div>}

export default function App(){
  const [section,setSection]=useState<Section>('inicio');
  const [mobileMenu,setMobileMenu]=useState(false);
  const [dataset,setDataset]=useState<Dataset>(examples[0]);
  const [textColumn,setTextColumn]=useState('comentario');
  const [labelColumn,setLabelColumn]=useState('area');
  const [options,setOptions]=useState<CleanOptions>(defaults);
  const [selectedDoc,setSelectedDoc]=useState(0);
  const [message,setMessage]=useState<{type:'error'|'success';text:string}|null>(null);
  const [busy,setBusy]=useState(false);
  const fileInput=useRef<HTMLInputElement>(null);
  const [viewRaw,setViewRaw]=useState(false);
  const [query,setQuery]=useState('');
  const [regexQuery,setRegexQuery]=useState('https?://\\S+');
  const [vectorMode,setVectorMode]=useState<'bow'|'tfidf'>('tfidf');
  const [maxFeatures,setMaxFeatures]=useState(20);
  const [minDf,setMinDf]=useState(1);
  const [maxDf,setMaxDf]=useState(1);
  const [ngrams,setNgrams]=useState<1|2>(1);
  const [compareA,setCompareA]=useState(0),[compareB,setCompareB]=useState(1);
  const [merges,setMerges]=useState(36);
  const [sentence,setSentence]=useState('El producto llegó rapidísimo y la atención fue excelente.');
  const [sentimentSelected,setSentimentSelected]=useState(0);
  const [k,setK]=useState(3),[iters,setIters]=useState(65);
  const [topicResult,setTopicResult]=useState<TopicResult|null>(null);
  const [trainResult,setTrainResult]=useState<RunResult[]|null>(null);
  const [trainError,setTrainError]=useState('');
  const [algorithm,setAlgorithm]=useState<Algorithm>('Regresión logística');
  const [tryText,setTryText]=useState('Necesito una factura corregida, el pago fue duplicado.');
  const [quizAnswers,setQuizAnswers]=useState<Record<number,number>>({});
  const [openConcept,setOpenConcept]=useState(0);
  const docs=useMemo(()=>dataset.rows.map(r=>r[textColumn]??''),[dataset,textColumn]);
  const processed=useMemo(()=>docs.map(text=>processText(text,options)),[docs,options]);
  const tokens=useMemo(()=>processed.map(p=>p.normalized),[processed]);
  const chartTokens=useMemo(()=>viewRaw?docs.map(d=>tokenize(d)):tokens,[viewRaw,docs,tokens]);
  const freq=useMemo(()=>frequencies(chartTokens),[chartTokens]);
  const unique=useMemo(()=>new Set(tokens.flat()).size,[tokens]);
  const selected=processed[Math.min(selectedDoc,Math.max(0,processed.length-1))];
  const vec=useMemo(()=>fitVectorizer(tokens,vectorMode,maxFeatures,minDf,maxDf,ngrams),[tokens,vectorMode,maxFeatures,minDf,maxDf,ngrams]);
  const sentimentDistribution=useMemo(()=>sentimentCounts(docs),[docs]);
  const bpe=useMemo(()=>learnBPE(tokens,merges),[tokens,merges]);
  const activeResult=trainResult?.find(x=>x.model.algorithm===algorithm);
  const prediction=useMemo(()=>activeResult?predict(activeResult.model,processText(tryText,options).normalized):null,[activeResult,tryText,options]);
  const onConfig=(key:keyof CleanOptions,value:boolean|string)=>setOptions(o=>({...o,[key]:value}));
  useEffect(()=>{setTopicResult(null);setTrainResult(null);setTrainError('');},[dataset,textColumn,labelColumn,options]);
  const changeDataset=(next:Dataset)=>{
    setDataset(next);
    const guessed=next.columns.find(c=>/^(comentario|texto|text|review|opinion|message|mensaje|descripcion|description|contenido|content)$/i.test(c))??next.columns.find(c=>next.rows.reduce((s,r)=>s+(r[c]||'').length,0)/Math.max(next.rows.length,1)>25)??next.columns[0];
    const label=next.columns.find(c=>/^(area|categoria|category|label|etiqueta|clase|sentimiento|intent|intencion)$/i.test(c))??next.columns.find(c=>c!==guessed)??guessed;
    setTextColumn(guessed);setLabelColumn(label);setSelectedDoc(0);setSentimentSelected(0);setCompareA(0);setCompareB(1);
    setMessage({type:'success',text:`Dataset «${next.name}» cargado correctamente: ${n(next.rows.length)} registros.`});
  };
  const loadFile=useCallback(async(file:File)=>{
    if(file.size>8*1024*1024){setMessage({type:'error',text:'Archivo demasiado grande. Máximo 8 MB en este laboratorio local.'});return;}
    setBusy(true);setMessage(null);
    try{
      const ext=file.name.split('.').pop()?.toLowerCase();
      let raw:Record<string,unknown>[]=[];
      if(ext==='csv'||ext==='tsv'){
        const text=await file.text();
        const parsed=Papa.parse<Record<string,unknown>>(text,{header:true,skipEmptyLines:'greedy',delimiter:ext==='tsv'?'\t':'',dynamicTyping:false});
        if(parsed.errors.length && !parsed.data.length) throw new Error(parsed.errors[0].message);
        raw=parsed.data;
      }else if(ext==='json'){
        const data:unknown=JSON.parse(await file.text());
        const array=Array.isArray(data)?data:(data&&typeof data==='object'?Object.values(data).find(Array.isArray):null);
        if(!Array.isArray(array))throw new Error('El JSON debe ser un arreglo de objetos o contener un arreglo en una propiedad.');
        raw=array as Record<string,unknown>[];
      }else if(ext==='txt'){
        raw=(await file.text()).split(/\r?\n/).map((text,i)=>({id:i+1,texto:text})).filter(x=>x.texto.trim());
      }else if(ext==='xlsx'){
        const {readSheet}=await import('read-excel-file/browser');
        const rows=await readSheet(file);
        if(!rows.length)throw new Error('La primera hoja del Excel está vacía.');
        const headers=rows[0].map((x,i)=>String(x??`columna_${i+1}`));
        raw=rows.slice(1).map(row=>Object.fromEntries(headers.map((h,j)=>[h,row[j]??''])));
      }else throw new Error('Formato no admitido. Usá CSV, TSV, JSON, TXT o XLSX.');
      if(!raw.length)throw new Error('No hay registros disponibles en el archivo.');
      const columns=[...new Set(raw.slice(0,100).flatMap(row=>Object.keys(row||{})))].filter(Boolean).slice(0,80);
      if(!columns.length)throw new Error('No se detectaron columnas.');
      const rows:Row[]=raw.slice(0,2000).map(r=>Object.fromEntries(columns.map(c=>[c,r[c]==null?'':String(r[c])])));
      changeDataset({name:file.name,source:'archivo',rows,columns});
      if(raw.length>2000)setMessage({type:'success',text:`Se importaron las primeras 2000 filas de ${n(raw.length)} por rendimiento. No se subieron a ningún servidor.`});
    }catch(e){setMessage({type:'error',text:e instanceof Error?e.message:'No se pudo leer el archivo.'});}
    finally{setBusy(false);if(fileInput.current)fileInput.current.value='';}
  },[]);
  const downloadProcessed=()=>{
    const all=dataset.rows.map((r,i)=>({...r,texto_limpio:processed[i].cleaned,tokens:processed[i].normalized.join(' | '),texto_procesado:processed[i].result}));
    saveBlob('\uFEFF'+Papa.unparse(all), 'nlp_laboratorio_procesado.csv','text/csv;charset=utf-8');
  };
  const navTo=(id:Section)=>{setSection(id);setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'});};
  const topicCompute=()=>{setBusy(true);setTimeout(()=>{try{setTopicResult(runLDA(tokens,k,iters));setMessage(null);}catch(e){setMessage({type:'error',text:String(e)})}finally{setBusy(false)}},25);};
  const classCompute=()=>{setBusy(true);setTrainError('');setTimeout(()=>{try{setTrainResult(trainModels(tokens,dataset.rows.map(r=>r[labelColumn]||''),docs));}catch(e){setTrainError(e instanceof Error?e.message:String(e));setTrainResult(null);}finally{setBusy(false)}},25);};
  const regexHits=useMemo(()=>{try{if(regexQuery.length>80 || /(\([^)]*[+*][^)]*\)[+*])/.test(regexQuery))return [];const r=new RegExp(regexQuery,'giu');const values:string[]=[];for(const match of (selected?.original||'').slice(0,1200).matchAll(r)){if(match[0])values.push(match[0]);if(values.length>=25)break;}return values;}catch{return []}},[regexQuery,selected]);
  const regexInvalid=()=>{if(regexQuery.length>80)return 'Usá un patrón de hasta 80 caracteres';if(/(\([^)]*[+*][^)]*\)[+*])/.test(regexQuery))return 'Patrón con cuantificadores anidados no permitido';try{new RegExp(regexQuery,'giu');return ''}catch(e){return e instanceof Error?e.message:String(e)}};
  const compareSimilarity=vec.matrix[compareA]&&vec.matrix[compareB]?cosine(vec.matrix[compareA],vec.matrix[compareB]):0;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu?'open':''}`}>
      <div className="brand"><div className="brand-icon"><span>N</span></div><div><strong>NLP<span>LAB</span></strong><small>BY CODERHOUSE · EDUCACIÓN</small></div><button className="mobile-close" onClick={()=>setMobileMenu(false)} aria-label="Cerrar menú"><X size={20}/></button></div>
      <div className="course-tag"><span className="live-pulse"/> EXPERIENCIA INTERACTIVA <span className="tag-arrow">↗</span></div>
      <div className="nav-caption">MI LABORATORIO</div>
      <nav aria-label="Navegación principal">{nav.map(x=>{const Icon=x.icon;return <button key={x.id} onClick={()=>navTo(x.id)} className={`nav-link ${section===x.id?'active':''}`}><Icon size={19}/><span><strong>{x.name}</strong><small>{x.sub}</small></span><span className="nav-unit">{x.unit}</span></button>})}</nav>
      <div className="sidebar-bottom"><div className="sidebar-card"><Sparkles size={20}/><b>Aprender haciendo.</b><p>Experimentá con tus datos sin instalar Python ni compartir archivos.</p><button onClick={()=>navTo('conceptos')}>Explorar contenidos <ArrowRight size={14}/></button></div><div className="sidebar-copy">EDICIÓN NLP · 2026</div></div>
    </aside>
    {mobileMenu&&<button className="overlay" onClick={()=>setMobileMenu(false)} aria-label="Cerrar navegación"/>}
    <main className="main">
      <header className="topbar"><div className="top-left"><button className="menu-button" onClick={()=>setMobileMenu(true)} aria-label="Abrir menú"><Menu size={23}/></button><span>DATA SCIENCE <ChevronRight size={13}/> PROCESAMIENTO DE LENGUAJE NATURAL</span></div><div className="top-right"><span className="privacy"><ShieldCheck size={15}/> Procesamiento local</span><span className="avatar">CH</span></div></header>
      {message&&<div className={`toast ${message.type}`} role="status"><span>{message.type==='success'?<Check size={17}/>:<AlertCircle size={17}/>} {message.text}</span><button onClick={()=>setMessage(null)} aria-label="Cerrar alerta"><X size={17}/></button></div>}
      <div className="content">
      {section==='inicio'&&<>
        <div className="hero"><div className="hero-content"><Pill tone="pink"><span className="spark-dot"/> TU LABORATORIO NLP</Pill><h1>De palabras a <em>conocimiento.</em></h1><p>Una experiencia para aprender procesamiento de lenguaje natural con datos reales, experimentos visuales y modelos que podés entrenar.</p><div className="hero-actions"><button className="btn btn-white" onClick={()=>navTo('datos')}>Comenzar laboratorio <ArrowRight size={18}/></button><button className="btn btn-ghost-white" onClick={()=>navTo('conceptos')}><BookOpen size={17}/> Ver temario</button></div><div className="hero-meta"><span><Check size={14}/> 100% interactivo</span><span><Check size={14}/> Sin backend</span><span><Check size={14}/> Datos privados</span></div></div><div className="hero-art" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit-center"><div className="orbit-inner"><span>NLP</span><small>LAB</small></div></div><span className="floating-signal signal-1">{`{ token: 1 }`}</span><span className="floating-signal signal-2">TF–IDF ↑</span><span className="floating-signal signal-3">[ 0.82, 0.13 ]</span></div></div>
        <div className="welcome-row"><div><span className="eyebrow">LABORATORIO EN VIVO</span><h2>Tu dataset. Tu experimento.</h2><p>Modificá cada etapa y comprobá en tiempo real cómo se transforma el lenguaje.</p></div><button className="btn btn-outline" onClick={()=>navTo('datos')}><FolderOpen size={17}/> Cargar mis datos</button></div>
        <div className="metrics-grid"><Metric icon={Database} label="Registros cargados" value={n(dataset.rows.length)} detail={dataset.source==='demo'?'Dataset de práctica':'Archivo personal'}/><Metric icon={BookOpen} label="Palabras únicas" value={n(unique)} detail="Después del pipeline"/><Metric icon={Workflow} label="Laboratorios" value="07" detail="Experimentos prácticos"/><Metric icon={BrainCircuit} label="Modelos de referencia" value="03" detail="NB · LR · SVM"/></div>
        <div className="welcome-row second"><div><span className="eyebrow">RUTA DE APRENDIZAJE</span><h2>8 estaciones, un mismo corpus.</h2><p>Los experimentos comparten tu dataset y la configuración activa de preprocesamiento.</p></div></div>
        <div className="module-grid">{nav.filter(x=>x.id!=='inicio').map((x,i)=>{const Icon=x.icon;return <button key={x.id} className="module-card" onClick={()=>navTo(x.id)}><div className="module-icon" style={{background:['#ffe0ec','#fff0db','#eae4ff','#dff4ef'][i%4],color:['#f23d79','#ee7e35','#8647d5','#299787'][i%4]}}><Icon size={22}/></div><div><span>UNIDAD {x.unit}</span><h3>{x.name}</h3><p>{x.sub}</p></div><ArrowRight size={18} className="module-arrow"/></button>})}</div>
        <div className="intro-banner"><div><span className="eyebrow">¿SABÍAS QUE...?</span><h3>Un dataframe puede contener texto, pero eso no lo vuelve un dato tabular en su semántica.</h3><p>El texto libre necesita representación: tokenización → vocabulario → vectores → modelos.</p></div><button className="btn btn-dark" onClick={()=>navTo('conceptos')}>Entender los fundamentos <ArrowRight size={17}/></button></div>
      </>}
      {section==='datos'&&<>
        <Title eyebrow="01 / PRIMEROS PASOS" title="Tu corpus, tus reglas." desc="Subí un dataset propio o usá uno de nuestros ejemplos. Elegí qué columna contiene texto y cuál es la etiqueta de clasificación."/>
        <div className="two-col upload-layout"><div className="panel"><PanelTitle title="Importar dataset" desc="CSV, TSV, XLSX, JSON o TXT · Hasta 8 MB"/><input ref={fileInput} type="file" accept=".csv,.tsv,.xlsx,.json,.txt" className="sr-only" onChange={e=>e.target.files?.[0]&&void loadFile(e.target.files[0])}/><div className="upload-area" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const file=e.dataTransfer.files?.[0];if(file)void loadFile(file)}}><div className="upload-symbol"><CloudUpload size={29}/></div><strong>Arrastrá tu archivo aquí</strong><p>El análisis se ejecuta en tu navegador. Nunca subimos los datos a un servidor.</p><button disabled={busy} className="btn btn-primary" onClick={()=>fileInput.current?.click()}>{busy?'Leyendo...':'Seleccionar archivo'} <ArrowRight size={16}/></button></div><div className="format-note"><ShieldCheck size={15}/> Tus datos no salen del navegador. Se utiliza la primera hoja en Excel.</div></div>
        <div className="panel"><PanelTitle title="Datasets de ejemplo" desc="Empezá a experimentar en un clic"/>{examples.map((ex,i)=><button className={`example-card ${dataset.name===ex.name?'selected':''}`} key={ex.name} onClick={()=>changeDataset(ex)}><div className="example-icon" style={{background:i===0?'#ffe1e9':'#eae2ff'}}>{i===0?<MessageSquareText size={20}/>:<Database size={20}/>}</div><div><strong>{ex.name}</strong><small>{i===0?'Reseñas etiquetadas por área y sentimiento':'Tickets multiclase de soporte técnico'}</small><span>{ex.rows.length} registros · {ex.columns.length} columnas</span></div><ChevronRight size={17}/></button>)}<button className="btn btn-outline btn-full" onClick={()=>saveBlob("\uFEFF"+Papa.unparse(examples[0].rows),"ejemplo_resenas_nlp.csv","text/csv;charset=utf-8")}><Download size={16}/> Descargar CSV de práctica</button><InfoNote title="¿Qué necesito para clasificar?" tone="tip">Una columna de texto y otra con etiquetas de clase conocidas. Para sentimiento y EDA basta con el texto.</InfoNote></div></div>
        <div className="panel spaced"><PanelTitle title="Configurar columnas" desc={`Dataset activo: ${dataset.name}`} action={<Pill tone="green">{n(dataset.rows.length)} filas</Pill>}/><div className="form-grid"><label className="field"><span>Columna de texto</span><select value={textColumn} onChange={e=>{setTextColumn(e.target.value);setSelectedDoc(0)}}>{dataset.columns.map(c=><option key={c}>{c}</option>)}</select><small>Origen de todas las transformaciones y análisis</small></label><label className="field"><span>Columna de etiquetas (opcional)</span><select value={labelColumn} onChange={e=>setLabelColumn(e.target.value)}>{dataset.columns.map(c=><option key={c}>{c}</option>)}</select><small>Se utiliza solo para clasificación supervisada</small></label></div><div className="data-summary"><span><Database size={16}/> {n(dataset.rows.length)} registros</span><span><Layers size={16}/> {dataset.columns.length} columnas</span><span><FileText size={16}/> {docs.filter(x=>x.trim()).length} textos no vacíos</span><span><BrainCircuit size={16}/> {new Set(dataset.rows.map(r=>r[labelColumn]||'')).size} etiquetas únicas</span></div></div>
        <div className="panel spaced"><PanelTitle title="Vista previa del archivo" desc="Primeras 8 filas · desplazamiento horizontal" action={<button className="btn btn-sm btn-outline" onClick={downloadProcessed}><Download size={15}/> Exportar procesado</button>}/><RowPreview columns={dataset.columns} rows={dataset.rows} max={8}/></div>
        <div className="bottom-next"><span>¿Listo para comenzar con el texto?</span><button className="btn btn-dark" onClick={()=>navTo('limpieza')}>Ir a preprocesamiento <ArrowRight size={18}/></button></div>
      </>}
      {section==='limpieza'&&<>
        <Title eyebrow="02 / PREPROCESAMIENTO" title="El arte de limpiar el lenguaje." desc="Activá y desactivá pasos, observá el resultado al instante y compará cómo cambian los tokens de un documento."/>
        <div className="two-col process-layout"><div className="panel"><PanelTitle title="Configurar pipeline" desc="Cada modificación se aplica a todo el corpus"/><div className="setting-group"><span>01 / LIMPIEZA ESTRUCTURAL</span><Toggler name="Minúsculas" checked={options.lowercase} onChange={v=>onConfig('lowercase',v)} desc="Hola → hola"/><Toggler name="Eliminar tildes" checked={options.accents} onChange={v=>onConfig('accents',v)} desc="canción → cancion"/><Toggler name="Eliminar etiquetas HTML" checked={options.removeHtml} onChange={v=>onConfig('removeHtml',v)} desc="Suprime tags, script y style"/><Toggler name="Eliminar enlaces URL" checked={options.removeUrls} onChange={v=>onConfig('removeUrls',v)} desc="https://..."/><Toggler name="Eliminar correos electrónicos" checked={options.removeEmails} onChange={v=>onConfig('removeEmails',v)} desc="nombre@dominio.com"/><Toggler name="Eliminar puntuación" checked={options.punctuation} onChange={v=>onConfig('punctuation',v)} desc="Cuidado: ¿!, emojis y negaciones"/><Toggler name="Eliminar números" checked={options.numbers} onChange={v=>onConfig('numbers',v)} desc="Según el dominio puede ser riesgoso"/></div><div className="setting-group"><span>02 / TOKENIZACIÓN Y FILTROS</span><Toggler name="Eliminar stop words (ES)" checked={options.stopwords} onChange={v=>onConfig('stopwords',v)} desc="Artículos, preposiciones y términos frecuentes"/><Toggler name="Preservar negaciones" checked={options.preserveNegation} onChange={v=>onConfig('preserveNegation',v)} desc="Mantiene no, nunca, ni, tampoco..."/></div><div className="setting-group"><span>03 / MORFOLOGÍA</span><label className="field"><span>Algoritmo morfológico</span><select value={options.morphology} onChange={e=>onConfig('morphology',e.target.value)}><option value="none">Sin reducción</option><option value="stemming">Snowball · stemming real en español</option><option value="lemma">Lematización aproximada (demo)</option></select></label><small className="micro-note">Snowball realiza stemming real. El lematizador del navegador es un léxico y reglas limitadas, no reemplaza el análisis contextual de spaCy.</small></div><button className="btn btn-outline btn-full" onClick={()=>setOptions(defaults)}><RefreshCw size={16}/> Restaurar valores</button></div>
        <div className="panel process-live"><PanelTitle title="Laboratorio en tiempo real" desc="Seleccioná un documento y seguí todas sus etapas" action={<Pill tone="pink">EN VIVO</Pill>}/><label className="field"><span>Documento a analizar</span><select value={Math.min(selectedDoc,docs.length-1)} onChange={e=>setSelectedDoc(Number(e.target.value))}>{docs.slice(0,120).map((d,i)=><option key={i} value={i}>#{i+1} · {truncated(d,68)}</option>)}</select></label><div className="pipeline-step"><span className="step-n">01</span><div><strong>Texto original</strong><p>{selected?.original||'—'}</p></div></div><div className="pipeline-step"><span className="step-n">02</span><div><strong>Normalización y regex</strong><p>{selected?.cleaned||'—'}</p></div></div><div className="pipeline-step"><span className="step-n">03</span><div><strong>Tokenización ({selected?.tokens.length||0} tokens)</strong><div className="token-grid">{selected?.tokens.map((t,i)=><span className="token" key={i}>{t}</span>)}</div></div></div><div className="pipeline-step final-step"><span className="step-n">04</span><div><strong>Filtrado y morfología ({selected?.normalized.length||0} tokens)</strong><div className="token-grid">{selected?.normalized.map((t,i)=><span className="token hot" key={i}>{t}</span>)}</div><p className="final-output">{selected?.result||'—'}</p></div></div><div className="process-stats"><div><strong>{selected?.original.length||0}</strong><span>Caracteres antes</span></div><div><strong>{selected?.result.length||0}</strong><span>Caracteres después</span></div><div><strong>{selected?.tokens.length?Math.round(100*(1-selected.normalized.length/selected.tokens.length)):0}%</strong><span>Tokens filtrados</span></div></div></div></div>
        <div className="panel spaced"><PanelTitle title="Zona de pruebas · Expresiones regulares" desc="Escribí una expresión y encontrá coincidencias sobre el documento original"/><div className="form-grid"><label className="field"><span>Patrón Regex · sin delimitadores /</span><input value={regexQuery} onChange={e=>setRegexQuery(e.target.value)} maxLength={150} placeholder="\\b\\d+\\b"/></label><div className="regex-results"><strong>{regexInvalid()?'Expresión inválida':`${regexHits.length} coincidencias encontradas`}</strong><div className="token-grid">{regexInvalid()?<span className="warn-text">{regexInvalid()}</span>:regexHits.map((h,i)=><span className="token" key={i}>{h}</span>)}</div></div></div><InfoNote title="Consejo de producción" tone="warn">Regex puede eliminar señales valiosas o causar cuelgues con patrones mal diseñados. El ejemplo no ejecuta reemplazos personalizados. Probá el patrón en textos de confianza.</InfoNote></div>
        <div className="panel spaced"><PanelTitle title="¿Por qué difieren stemming y lematización?"/><div className="comparison-cards"><div><Pill tone="orange">STEMMING · Snowball</Pill><h3>Corre rápido, aproxima mucho.</h3><p>Recorta palabras mediante reglas morfológicas. El resultado puede ser «corr» en lugar de «correr».</p></div><div><Pill tone="pink">LEMATIZACIÓN · Lingüística</Pill><h3>Busca una forma canónica.</h3><p>Para desambiguar «fue» entre «ser» e «ir» se necesita contexto y un modelo lingüístico. Nuestra demo no tiene esa capacidad.</p></div></div><details className="code-details"><summary><Code2 size={16}/> Cómo hacerlo con spaCy en Python <ChevronDown size={16}/></summary><pre><code>{pythonReference}</code></pre></details><button className="btn btn-dark" onClick={downloadProcessed}><Download size={17}/> Descargar dataset procesado</button></div>
      </>}
      {section==='explorar'&&<>
        <Title eyebrow="03 / ANÁLISIS EXPLORATORIO" title="Las palabras tienen patrones." desc="Explorá las frecuencias, la distribución de longitudes y la relevancia de los términos de tu corpus."/>
        <div className="metric-strip"><div><strong>{n(docs.length)}</strong><span>Documentos</span></div><div><strong>{n(freq.reduce((s,x)=>s+x.count,0))}</strong><span>Tokens totales</span></div><div><strong>{n(freq.length)}</strong><span>Vocabulario</span></div><div><strong>{(tokens.reduce((s,t)=>s+t.length,0)/Math.max(1,tokens.length)).toFixed(1)}</strong><span>Tokens por documento</span></div></div>
        <div className="panel"><PanelTitle title="Nube de palabras" desc="El tamaño representa frecuencia de aparición" action={<div className="segmented"><button className={!viewRaw?'on':''} onClick={()=>setViewRaw(false)}>Procesado</button><button className={viewRaw?'on':''} onClick={()=>setViewRaw(true)}>Original</button></div>}/><WordCloud words={freq}/><div className="cloud-caption"><span>MENOS FRECUENTES</span><span className="gradient-line"/><span>MÁS FRECUENTES</span></div></div>
        <div className="two-col spaced"><div className="panel"><PanelTitle title="Top 12 palabras" desc="Frecuencia absoluta"/><div className="chart-box"><ResponsiveContainer width="100%" height="100%"><BarChart data={freq.slice(0,12)} layout="vertical" margin={{left:18,right:12}}><CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#efe9e5"/><XAxis type="number" tick={{fontSize:11}}/><YAxis width={92} type="category" dataKey="word" tick={{fontSize:11}}/><Tooltip/><Bar dataKey="count" name="Apariciones" fill="#fa538e" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div></div><div className="panel"><PanelTitle title="Longitud de documentos" desc="Cantidad de tokens por documento"/><div className="chart-box"><ResponsiveContainer width="100%" height="100%"><BarChart data={documentLengths(chartTokens)}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#efe9e5"/><XAxis dataKey="bucket" tick={{fontSize:11}}/><YAxis allowDecimals={false} tick={{fontSize:11}}/><Tooltip/><Bar dataKey="count" name="Documentos" fill="#a66af2" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></div></div>
        <div className="panel spaced"><PanelTitle title="Bigrama: dos palabras, más contexto" desc="Secuencias de dos tokens consecutivos (orden conservado)" action={<button className="btn btn-sm btn-outline" onClick={()=>saveBlob('\uFEFF'+Papa.unparse(freq.slice(0,250)),'frecuencias_nlp.csv','text/csv;charset=utf-8')}><Download size={15}/> CSV frecuencias</button>}/><div className="bigram-list">{frequencies(chartTokens.map(d=>d.slice(1).map((t,i)=>`${d[i]} ${t}`))).slice(0,12).map((x,i)=><div className="bigram" key={x.word}><span>{String(i+1).padStart(2,'0')}</span><strong>{x.word}</strong><div className="mini-bar"><span style={{width:`${100*x.count/Math.max(1,chartTokens.length)}%`}}/></div><small>{x.count}</small></div>)}</div></div><InfoNote title="Interpretación: frecuencia no equivale a importancia" tone="tip">«Servicio» puede repetirse mucho porque todas las reseñas lo mencionan. TF-IDF le dará menos peso que a una palabra específica de un documento.</InfoNote>
      </>}
      {section==='vectores'&&<>
        <Title eyebrow="04 / REPRESENTACIONES" title="Del texto a los números." desc="Construí matrices Bag of Words y TF-IDF, explorá la dispersión y compará documentos por similitud coseno."/>
        <div className="panel"><PanelTitle title="Configuración de vectorización" desc="Los parámetros se recalculan en tiempo real"/><div className="vector-form"><div className="segmented large"><button className={vectorMode==='bow'?'on':''} onClick={()=>setVectorMode('bow')}>Bag of Words</button><button className={vectorMode==='tfidf'?'on':''} onClick={()=>setVectorMode('tfidf')}>TF-IDF (L2)</button></div><label className="field"><span>Máx. features <strong>{maxFeatures}</strong></span><input type="range" min="5" max="65" value={maxFeatures} onChange={e=>setMaxFeatures(Number(e.target.value))}/></label><label className="field"><span>min_df (documentos) <strong>{minDf}</strong></span><input type="range" min="1" max={Math.max(1,Math.min(6,docs.length))} value={minDf} onChange={e=>setMinDf(Number(e.target.value))}/></label><label className="field"><span>max_df <strong>{Math.round(maxDf*100)}%</strong></span><input type="range" min="0.4" max="1" step="0.05" value={maxDf} onChange={e=>setMaxDf(Number(e.target.value))}/></label><label className="field"><span>Tipo de n-grama</span><select value={ngrams} onChange={e=>setNgrams(Number(e.target.value) as 1|2)}><option value={1}>Unigramas</option><option value={2}>Unigramas + bigramas</option></select></label></div></div>
        <div className="metrics-grid spaced"><Metric label="Documentos" value={n(docs.length)} detail="Filas de la matriz" icon={Database}/><Metric label="Features" value={vec.terms.length} detail="Columnas resultantes" icon={Layers}/><Metric label="Sparsity" value={pct(vec.sparse)} detail="Celdas con valor 0" icon={Split}/><Metric label="Tipo" value={vectorMode==='bow'?'BoW':'TF-IDF'} detail={vectorMode==='bow'?'Conteos enteros':'Ponderación con L2'} icon={Gauge}/></div>
        <div className="panel spaced"><PanelTitle title="Matriz documento × término" desc="Primeros 10 documentos y hasta 14 características · intensidad proporcional al valor"/><div className="table-scroll"><table className="matrix-table"><thead><tr><th>Documento</th>{vec.terms.slice(0,14).map(w=><th key={w} title={w}>{truncated(w,14)}</th>)}</tr></thead><tbody>{vec.matrix.slice(0,10).map((row,i)=><tr key={i}><th>Doc {i+1}</th>{row.slice(0,14).map((value,j)=><td key={j}><span className="heat-cell" title={`${vec.terms[j]}: ${value.toFixed(4)}`} style={{background:value?`rgba(246,58,131,${Math.min(.88,.12+value/(Math.max(...row)||1)*.75)})`:'#f8f5f3',color:value>.5?'#fff':'#332733'}}>{vectorMode==='bow'?value:value.toFixed(2)}</span></td>)}</tr>)}</tbody></table></div><InfoNote title="Interpretación" tone="info">BoW cuenta apariciones. TF-IDF de esta app usa IDF suavizado y normalización L2 sobre cada documento, como un baseline habitual. Un vocabulario muy pequeño o un max_df estricto puede producir vectores vacíos.</InfoNote></div>
        <div className="two-col spaced"><div className="panel"><PanelTitle title="Términos y ponderaciones" desc="IDF de las primeras 12 características"/><div className="chart-box"><ResponsiveContainer width="100%" height="100%"><BarChart layout="vertical" data={vec.terms.slice(0,12).map((term,i)=>({term,idf:Number(vec.idf[i].toFixed(2))}))}><XAxis type="number" domain={[0,'auto']} tick={{fontSize:11}}/><YAxis dataKey="term" type="category" width={93} tick={{fontSize:11}}/><Tooltip/><Bar dataKey="idf" name="IDF" fill="#ff884b" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div></div><div className="panel"><PanelTitle title="Similitud coseno" desc="Qué tan parecidos son los vectores de dos documentos"/><div className="form-stack"><label className="field"><span>Documento A</span><select value={Math.min(compareA,docs.length-1)} onChange={e=>setCompareA(+e.target.value)}>{docs.slice(0,80).map((d,i)=><option value={i} key={i}>#{i+1} · {truncated(d,43)}</option>)}</select></label><label className="field"><span>Documento B</span><select value={Math.min(compareB,docs.length-1)} onChange={e=>setCompareB(+e.target.value)}>{docs.slice(0,80).map((d,i)=><option value={i} key={i}>#{i+1} · {truncated(d,43)}</option>)}</select></label></div><div className="similarity-score"><strong>{compareSimilarity.toFixed(3)}</strong><span>SIMILITUD COSENO</span><div className="similarity-track"><span style={{width:`${Math.max(0,compareSimilarity)*100}%`}}/></div><small>0 = sin términos compartidos · 1 = misma dirección vectorial</small></div></div></div>
        <div className="panel spaced"><PanelTitle title="Tokenización BPE: laboratorio de subpalabras" desc="Entrenamos un algoritmo simplificado de fusiones frecuentes sobre las palabras de tu corpus"/><div className="form-grid"><label className="field"><span>Fusiones de pares: {merges}</span><input type="range" min="0" max="100" value={merges} onChange={e=>setMerges(+e.target.value)}/></label><label className="field"><span>Probá una palabra o frase</span><input value={sentence} onChange={e=>setSentence(e.target.value)} /></label></div><div className="token-grid bpe-output">{bpeTokenize(sentence,bpe).map((w,i)=><span className="token hot" key={i}>{w}</span>)}</div><div className="small-stats"><Pill tone="orange">{bpe.length} fusiones aprendidas</Pill><Pill>{bpeTokenize(sentence,bpe).length} subpalabras</Pill><Pill>{[...new Set(tokens.flat())].length} palabras originales</Pill></div><InfoNote title="BPE no es lo mismo que WordPiece" tone="warn">Esta demo entrena fusiones de caracteres del corpus local. No reproduce los tokens de GPT/BERT ni las reglas completas de sus pretokenizadores. Un tokenizador preentrenado necesita su vocabulario real.</InfoNote></div>
      </>}
      {section==='sentimientos'&&<>
        <Title eyebrow="05 / ANÁLISIS DE SENTIMIENTO" title="¿Qué dicen las emociones?" desc="Explorá polaridad positiva, negativa o neutra con un léxico transparente, intensificadores y manejo básico de negación."/>
        <div className="metric-strip"><div><strong>{sentimentDistribution.find(x=>x.name==='Positivo')?.value||0}</strong><span>Positivos</span></div><div><strong>{sentimentDistribution.find(x=>x.name==='Neutro')?.value||0}</strong><span>Neutros</span></div><div><strong>{sentimentDistribution.find(x=>x.name==='Negativo')?.value||0}</strong><span>Negativos</span></div><div><strong>ES</strong><span>Léxico disponible</span></div></div>
        <div className="two-col spaced"><div className="panel"><PanelTitle title="Distribución de polaridad" desc="Clasificación del corpus completo"/><div className="chart-box pie-box"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sentimentDistribution} cx="50%" cy="48%" innerRadius={62} outerRadius={102} paddingAngle={4} dataKey="value" nameKey="name">{sentimentDistribution.map((_,i)=><Cell fill={palette[[0,2,1][i]]} key={i}/>)}</Pie><Tooltip/><Legend verticalAlign="bottom"/></PieChart></ResponsiveContainer></div></div><div className="panel"><PanelTitle title="Probá una frase" desc="Señala palabras que suman o restan sentimiento"/><textarea className="text-test" value={sentence} onChange={e=>setSentence(e.target.value)} rows={4} maxLength={1000}/><div className="sentiment-verdict"><Pill tone={scoreSentiment(sentence).label==='Positivo'?'pink':scoreSentiment(sentence).label==='Negativo'?'orange':'light'}>{scoreSentiment(sentence).label}</Pill><strong>{scoreSentiment(sentence).value.toFixed(1)} pts</strong></div><div className="token-grid">{scoreSentiment(sentence).hits.map((h,i)=><span className={`token ${h.weight>0?'positive':'negative'}`} key={i}>{h.word} ({h.weight>0?'+':''}{h.weight})</span>)}</div><p className="muted-note">El léxico suma y resta pesos; invierte el signo si detecta una negación cercana (ventana de 3 tokens).</p></div></div>
        <div className="panel spaced"><PanelTitle title="Auditoría de predicciones" desc="Seleccioná un documento y revisá por qué se le asignó su polaridad"/><div className="sentiment-audit"><div className="audit-table">{docs.slice(0,45).map((text,i)=>{const res=scoreSentiment(text);return <button className={`audit-row ${sentimentSelected===i?'active':''}`} onClick={()=>setSentimentSelected(i)} key={i}><span>#{i+1}</span><strong>{truncated(text,90)}</strong><Pill tone={res.label==='Positivo'?'pink':res.label==='Negativo'?'orange':'light'}>{res.label}</Pill></button>})}</div><div className="audit-detail"><span className="eyebrow">DOCUMENTO {sentimentSelected+1}</span><h3>Interpretación del léxico</h3><blockquote>“{docs[sentimentSelected]}”</blockquote><div className="verdict-big"><span>PUNTAJE</span><strong>{scoreSentiment(docs[sentimentSelected]||'').value.toFixed(1)}</strong></div><div className="token-grid">{scoreSentiment(docs[sentimentSelected]||'').hits.map((h,i)=><span className={`token ${h.weight>0?'positive':'negative'}`} key={i}>{h.word} {h.weight>0?'+':''}{h.weight}</span>)}</div><small>Las palabras que no aparecen en el léxico aportan 0 puntos.</small></div></div></div><InfoNote title="Modelo baseline: no entiende sarcasmo ni contexto profundo" tone="warn">«¡Genial, llegó roto!» puede ser clasificado erróneamente. Para producción habría que evaluar modelos entrenados en español, métricas por dominio y errores humanos.</InfoNote>
      </>}
      {section==='topicos'&&<>
        <Title eyebrow="06 / MODELADO NO SUPERVISADO" title="Descubrí los temas ocultos." desc="Entrená Latent Dirichlet Allocation (LDA) mediante muestreo de Gibbs sobre tus documentos preprocesados."/>
        <div className="panel"><PanelTitle title="Entrenar modelo LDA" desc="El proceso se ejecuta localmente y puede variar al modificar el corpus"/><div className="topic-config"><label className="field"><span>Número de tópicos <strong>{k}</strong></span><input type="range" min={2} max={6} value={k} onChange={e=>setK(+e.target.value)}/></label><label className="field"><span>Iteraciones Gibbs <strong>{iters}</strong></span><input type="range" min={25} max={125} step={10} value={iters} onChange={e=>setIters(+e.target.value)}/></label><div className="topic-button"><button className="btn btn-primary" disabled={busy||tokens.every(t=>!t.length)} onClick={topicCompute}><Play size={17}/> {busy?'Calculando...':'Descubrir tópicos'}</button></div></div><div className="format-note"><Info size={15}/> Para mantener la fluidez se usan como máximo 300 documentos, 75 tokens por documento y 220 términos frecuentes. Probabilidad estimada; no son etiquetas de verdad.</div></div>
        {!topicResult?<div className="launch-pad"><div><Sparkles size={30}/></div><h2>Encontrá patrones que aún no ves.</h2><p>Presioná «Descubrir tópicos» para entrenar un LDA real sobre tus textos. Vas a encontrar grupos de palabras y la asignación probabilística de cada documento.</p><button className="btn btn-dark" onClick={topicCompute} disabled={busy}>Ejecutar experimento <ArrowRight size={17}/></button></div>:topicResult.topics.length===0?<Empty title="Vocabulario insuficiente" detail="El modelo necesita términos que aparezcan al menos dos veces. Revisá el dataset y las reglas de limpieza."/>:<><div className="topic-grid spaced">{topicResult.topics.map((words,t)=><div className="panel topic-card" key={t}><div className="topic-head"><span className="topic-number" style={{background:palette[t]}}>0{t+1}</span><div><small>TÓPICO DETECTADO</small><h3>Tema {t+1}</h3></div><Pill>{topicResult.assignments.filter(x=>x===t).length} docs</Pill></div>{words.map((w,i)=><div className="topic-word" key={w.word}><span>{w.word}</span><div><i style={{width:`${100*w.weight/(words[0]?.weight||1)}%`,background:palette[t]}}/></div><small>{(w.weight*100).toFixed(1)}%</small></div>)}</div>)}</div><div className="panel spaced"><PanelTitle title="Asignación dominante por documento" desc="Muestras del corpus con su tópico más probable"/><div className="table-scroll"><table className="data-table"><thead><tr><th>Documento</th><th>Contenido</th><th>Tópico dominante</th><th>Probabilidad</th></tr></thead><tbody>{topicResult.assignments.slice(0,16).map((a,i)=><tr key={i}><td>{i+1}</td><td>{truncated(docs[i],95)}</td><td><span className="legend-dot" style={{background:palette[a]}}/> Tema {a+1}</td><td>{pct(topicResult.distribution[i]?.[a]||0)}</td></tr>)}</tbody></table></div></div><InfoNote title="No confundas tópicos con etiquetas humanas" tone="tip">LDA agrupa coocurrencias; para nombrar un tópico «Facturación» o «Envíos» hace falta interpretación. Con pocos textos, los resultados pueden ser inestables.</InfoNote></>}
      </>}
      {section==='clasificacion'&&<>
        <Title eyebrow="07 / MODELOS SUPERVISADOS" title="Entrená. Medí. Compará." desc="Entrená tres clasificadores clásicos con TF-IDF, un split estratificado 80/20 y métricas de evaluación fuera de muestra."/>
        <div className="panel"><PanelTitle title="Configuración del benchmark" desc="El fit del vectorizador se hace solo con train para evitar data leakage"/><div className="class-setup"><div><span className="setup-label">CARACTERÍSTICAS</span><strong>TF-IDF + tokens procesados</strong><small>Máximo 450 términos, norma L2</small></div><div><span className="setup-label">ETIQUETA OBJETIVO</span><strong>{labelColumn}</strong><small>{new Set(dataset.rows.map(r=>r[labelColumn])).size} clases distintas</small></div><div><span className="setup-label">PARTICIÓN</span><strong>80% train / 20% test</strong><small>Estratificado · semilla fija</small></div><button className="btn btn-primary" disabled={busy} onClick={classCompute}><Play size={17}/> {busy?'Entrenando...':'Entrenar los 3 modelos'}</button></div>{trainError&&<InfoNote title="No se pudo entrenar" tone="warn">{trainError}. Elegí otra columna en «Mis datasets».</InfoNote>}</div>
        {!trainResult?<div className="launch-pad"><div><BrainCircuit size={32}/></div><h2>De la intuición a la predicción.</h2><p>Compará Multinomial Naive Bayes, regresión logística y SVM lineal. El dataset de ejemplo ya incluye categorías para entrenar.</p><button className="btn btn-dark" onClick={classCompute} disabled={busy}>Entrenar ahora <ArrowRight size={17}/></button></div>:<><div className="metrics-grid spaced"><Metric label="Ejemplos de entrenamiento" value={trainResult[0].metrics.trained} detail="Solo train para el vectorizador" icon={Database}/><Metric label="Ejemplos de test" value={trainResult[0].metrics.tested} detail="No vistos durante el fit" icon={Split}/><Metric label="Mejor accuracy" value={pct(Math.max(...trainResult.map(x=>x.metrics.accuracy)))} detail="Evaluación holdout" icon={Target}/><Metric label="Mejor F1 macro" value={pct(Math.max(...trainResult.map(x=>x.metrics.macroF1)))} detail="Ponderación igual por clase" icon={TrendingUp}/></div><div className="panel spaced"><PanelTitle title="Comparativa de modelos" desc="Seleccioná un algoritmo para ver su matriz de confusión"/><div className="model-comparison">{trainResult.map(r=><button key={r.model.algorithm} onClick={()=>setAlgorithm(r.model.algorithm)} className={`model-card ${algorithm===r.model.algorithm?'active':''}`}><span>{r.model.algorithm}</span><strong>{pct(r.metrics.accuracy)}</strong><small>Accuracy · F1 macro {pct(r.metrics.macroF1)}</small><div className="meter"><i style={{width:`${r.metrics.macroF1*100}%`}}/></div></button>)}</div></div><div className="two-col spaced"><div className="panel"><PanelTitle title={`Matriz de confusión · ${algorithm}`} desc="Filas = clase real · columnas = predicha"/><div className="table-scroll"><table className="confusion-table"><thead><tr><th>Real ↓ / Pred. →</th>{activeResult?.metrics.classes.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{activeResult?.metrics.matrix.map((row,i)=><tr key={i}><th>{activeResult.metrics.classes[i]}</th>{row.map((v,j)=><td className={i===j?'diagonal':''} key={j}>{v}</td>)}</tr>)}</tbody></table></div><div className="mini-metrics">{activeResult?.metrics.classes.map((c,i)=><div key={c}><b>{c}</b><span>Prec. {pct(activeResult.metrics.precision[i])}</span><span>Recall {pct(activeResult.metrics.recall[i])}</span><span>F1 {pct(activeResult.metrics.f1[i])}</span></div>)}</div></div><div className="panel"><PanelTitle title="Probar predicción" desc="El modelo elegido clasifica un mensaje nuevo"/><textarea className="text-test" value={tryText} onChange={e=>setTryText(e.target.value)} rows={5} maxLength={1500}/><div className="prediction"><span>CLASE PREDICHA</span><strong>{prediction}</strong><small>Predicción del baseline · no es una probabilidad calibrada</small></div><div className="training-facts"><span><Check size={15}/> Train y test separados</span><span><Check size={15}/> TF-IDF fitted solo en train</span><span><Check size={15}/> F1 por clase</span></div></div></div><div className="panel spaced"><PanelTitle title="Errores de clasificación" desc="Analizá documentos mal predichos en el conjunto test"/>{activeResult?.validation.filter(v=>v.trueLabel!==v.pred).length?<div className="table-scroll"><table className="data-table"><thead><tr><th>Texto</th><th>Clase real</th><th>Predicción</th></tr></thead><tbody>{activeResult.validation.filter(v=>v.trueLabel!==v.pred).slice(0,15).map((r,i)=><tr key={i}><td>{truncated(r.text,140)}</td><td>{r.trueLabel}</td><td>{r.pred}</td></tr>)}</tbody></table></div>:<div className="no-errors"><Check size={20}/> No hubo errores en el conjunto de test de esta partición.</div>}</div><InfoNote title="Resultados de laboratorio, no validación industrial" tone="warn">Este es un split holdout pequeño. En producción: cross-validation, tuning, análisis de desbalance, métricas por grupo y evaluación en datos de otro período. En la práctica puede existir sesgo en el dataset sintético.</InfoNote></>}
      </>}
      {section==='conceptos'&&<>
        <Title eyebrow="08 / AULA INTERACTIVA" title="Aprendé el porqué de cada paso." desc="Conceptos explicados con ejemplos cotidianos. Abrí tarjetas, revisá errores comunes y comprobá tu comprensión."/>
        <div className="learning-hero"><div><Pill tone="pink">GUÍA DE ESTUDIO</Pill><h2>La mejor forma de aprender NLP es romperlo, observarlo y volver a construirlo.</h2><p>Recorré los fundamentos desde datos no tabulares hasta la evaluación de modelos clásicos de clasificación de texto.</p></div><div className="learning-image"><img src="/coderhouse-referencia.png" alt="Referencia estética proporcionada de Coderhouse"/></div></div>
        <div className="welcome-row second"><div><span className="eyebrow">GLOSARIO ESENCIAL</span><h2>16 conceptos. Ejemplos sin vueltas.</h2></div></div><div className="concept-grid">{chapters.map((c,i)=><button key={i} className={`concept-card ${openConcept===i?'expanded':''}`} onClick={()=>setOpenConcept(openConcept===i?-1:i)} aria-expanded={openConcept===i}><div><span>{String(i+1).padStart(2,'0')}</span><h3>{c.title}</h3><ChevronDown size={18}/></div>{openConcept===i&&<section><p>{c.text}</p><em>{c.example}</em></section>}</button>)}</div>
        <div className="panel spaced"><PanelTitle title="Mini desafío: ¿dominás los conceptos?" desc="Elegí una respuesta y descubrí la explicación"/><div className="quiz-grid">{quiz.map((q,i)=><div className="quiz-card" key={i}><div className="quiz-header"><span>PREGUNTA {i+1}/{quiz.length}</span><strong>{q.q}</strong></div><div className="quiz-answers">{q.answers.map((a,j)=><button key={j} onClick={()=>setQuizAnswers(old=>({...old,[i]:j}))} className={`${quizAnswers[i]===j?'picked':''} ${quizAnswers[i]!==undefined&&j===q.correct?'correct':''} ${quizAnswers[i]===j&&j!==q.correct?'incorrect':''}`}><span>{String.fromCharCode(65+j)}</span>{a}{quizAnswers[i]===j&&<Check size={15}/>}</button>)}</div>{quizAnswers[i]!==undefined&&<div className={`quiz-feedback ${quizAnswers[i]===q.correct?'ok':'fail'}`}><strong>{quizAnswers[i]===q.correct?'¡Correcto!':'Casi. Revisemos:'}</strong> {q.explain}</div>}</div>)}</div><div className="quiz-score">Puntaje: <strong>{quiz.filter((q,i)=>quizAnswers[i]===q.correct).length} / {quiz.length}</strong><button className="btn btn-sm btn-outline" onClick={()=>setQuizAnswers({})}><RefreshCw size={14}/> Reiniciar</button></div></div>
        <div className="panel spaced"><PanelTitle title="Casos reales para debatir en clase"/><div className="case-grid"><div><span>01 · E-COMMERCE</span><h3>¿Por qué recibo reclamos aunque el score general sea positivo?</h3><p>Un sentimiento global puede ocultar un problema específico de envíos. Combiná tópicos, sentimiento y categorías.</p></div><div><span>02 · LEGAL TECH</span><h3>¿Cómo encuentro contratos con terminología similar?</h3><p>Probá TF-IDF y similitud coseno, luego evaluá cuándo los embeddings contextualizados aportarían mejoras.</p></div><div><span>03 · CIBERSEGURIDAD</span><h3>¿Cómo distinguir correos legítimos de phishing?</h3><p>Entrená Naive Bayes o SVM con etiquetas, evaluá falsos negativos y elegí el umbral según el costo del error.</p></div></div></div>
      </>}
      <footer className="footer"><div><span className="footer-logo">NLP<span>LAB</span></span> <span>Experiencia educativa · Palabras → Datos → Decisiones</span></div><div>Inspirado en la identidad visual de Coderhouse · Proyecto educativo independiente</div></footer>
      </div>
    </main>
  </div>;
}
